select lot_id from inv_inventory_lot where lot_id in
#{lotId}
order by lot_id for update

select location_id from inv_warehouse_location where location_id in
#{locationId}
order by location_id for update

select b.balance_id, b.item_type, b.item_id, b.warehouse_id, b.lot_id, l.lot_no, l.expiry_date, coalesce(b.last_in_time, b.create_time, l.create_time) received_at, b.location_id, w.location_code, b.available_quantity, b.version from inv_stock_balance_detail b inner join inv_inventory_lot l on l.lot_id = b.lot_id and l.warehouse_id = b.warehouse_id and l.item_type = b.item_type and l.item_id = b.item_id inner join inv_warehouse_location w on w.location_id = b.location_id and w.warehouse_id = b.warehouse_id where b.balance_id in
#{balanceId}
and b.available_quantity > 0 and l.qc_status in ('passed', 'concession') and l.lot_status = 'active' and (l.expiry_date is null or l.expiry_date >= current_date) and w.status = '0' and w.is_virtual = '0' and w.location_type not in ('receiving', 'quarantine', 'virtual') order by b.balance_id

select serial_id, balance_id, serial_no, serial_status from inv_inventory_serial where balance_id in
#{balanceId}
order by serial_id for update

mapper.update:
update inv_stock_balance_detail
set current_quantity = current_quantity - #{quantity},
    available_quantity = available_quantity - #{quantity},
    total_cost = total_cost - #{deductCost},
    last_out_time = sysdate(),
    version = version + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where balance_id = #{balanceId}
  and version = #{version}
  and #{quantity} > 0
  and #{deductCost} >= 0
  and current_quantity >= #{quantity}
  and available_quantity >= #{quantity}
  and total_cost >= #{deductCost}

update inv_inventory_serial
set serial_status = 'shipped',
    update_by = #{updateBy},
    update_time = sysdate()
where serial_id = #{serialId}
  and balance_id = #{balanceId}
  and warehouse_id = #{warehouseId}
  and lot_id = #{lotId}
  and location_id = #{locationId}
  and serial_status = 'available'
